    var __lockMark=String(zdjl.getVar("自己农场OCR锁定标记","global")||"");
    var __wantMark=__runMark+"|"+__accountMark;
    if(__lockMark!==__wantMark) locked="否";
    if(locked!="是"){
        var ocrFn=null;
        var farmArea=null;

        // 先取现成的全局OCR函数与“植物状态”区域。
        try{ ocrFn=zdjl.getVar("ocrText","global"); }catch(__getOcrErr){}
        try{ farmArea=zdjl.getVar("植物状态","global"); }catch(__getAreaErr){}
