        if(typeof ocrFn!="function"){
            try{ if(typeof ocrText=="function") ocrFn=ocrText; }catch(__directOcrErr){}
        }
        if(!farmArea){
            try{ if(typeof 植物状态!="undefined") farmArea=植物状态; }catch(__directAreaErr){}
        }

        // OCR函数或区域缺失时，先补跑正式初始化，再重新取得两者。
        if(typeof ocrFn!="function" || !farmArea){
            try{
                zdjl.runAction({
                    "type":"执行脚本","delay":"0","delayUnit":1,"repeatCount":1,
                    "desc":"自己农场OCR前补初始化","filePath":"初始化OCR.zjs",
                    "runArgs":"","continueCurrentAfterFinish":true,"useCurrentGestureMatrix":false
                });
            }catch(__initOcrErr){}
            try{ ocrFn=zdjl.getVar("ocrText","global"); }catch(__getOcrErr2){}
            try{ farmArea=zdjl.getVar("植物状态","global"); }catch(__getAreaErr2){}
            if(typeof ocrFn!="function"){
                try{ if(typeof ocrText=="function") ocrFn=ocrText; }catch(__directOcrErr2){}
            }
            if(!farmArea){
                try{ if(typeof 植物状态!="undefined") farmArea=植物状态; }catch(__directAreaErr2){}
            }
        }

        var raw="";
        if(typeof ocrFn=="function" && farmArea){
            // 最多三次。整块植物状态正常会包含“昵称的农场/等级/作物/成熟”等多行文字；
            // 只有极短结果（例如单独“农场”）不锁定，避免错误身份污染后续所有区。
            for(var __i=0;__i<3;__i++){
                try{ raw=String(ocrFn(farmArea,"medium")||""); }
                catch(__farmOcrErr){ raw=""; }
                raw=raw.replace(/\r\n?/g,"\n").trim();
                if(raw.replace(/\s/g,"").length>=4) break;
                if(__i<2){ try{ zdjl.sleep(300); }catch(__retrySleepErr){} }
            }
        }

        zdjl.setVar("自己农场OCR原文",raw,"global");
        if(raw.replace(/\s/g,"").length>=4){
            zdjl.setVar("自己农场OCR已锁定","是","global");
            zdjl.setVar("自己农场OCR锁定标记",__wantMark,"global");
            try{ zdjl.toast("收割身份OCR√",1200); }catch(__ocrToastErr){}
