{"type":"运行JS代码","delayUnit":1,"desc":"OCR SDK初始化（全局仅缺失时执行）","jsCode":"/**
 * 自动精灵 OCR SDK
 * 对接 OcrServer HTTP 服务 (127.0.0.1:9530)
 *
 * 维度说明:
 *   type  = 精度档位: high(高精度/慢) / low(低精度/快)
 *   model = 模型档位: tiny(默认/最快) / small(更准) / medium(最高精度,速度略慢)
 *   两者正交，可自由组合，例如 {type:'high', model:'medium'} 取最高精度
 *   后端接受 model 取值: tiny | small | medium (small 可写 s/v6_small/v6small；medium 可写 m/v6_medium/v6medium)
 *   后端响应会回显 "model" 字段，可用 result.model 读取实际使用的档位
 *
 * 多模型常驻 + 单模型精度（element 写 'model' 或 'model,type' 简写）:
 *   init({ models: ['tiny','small','medium'] })                          // 全部用默认精度 this.type
 *   init({ models: ['tiny','small,high','medium,high'] })                // 用逗号简写单独指定精度
 *   init({ models: [{model:'medium',type:'high'}] })                     // 也兼容完整对象写法
 *   之后用序号/模型名调用即自动带上该模型配置的精度:
 *     ocr(area, 1)            用 models[0] 及其配置的精度
 *     ocr(area, 2)            用 models[1] 及其配置的精度
 *     ocr(area, 'medium')     同效；未单独配置精度则走默认 this.type
 *     ocr(area, {model:'medium', type:'low'})  直接传对象覆盖
 *   序号对所有文字方法同样有效: hasText(area, '开始', 2)
 *
 * 方法说明:
 *   ocr(area, arg)           - OCR识别，返回 {data, timeout, model}
 *   hasText(area, text, arg) - 是否出现指定文字
 *   clickText(area, text, arg) - 点击指定文字
 *   clickMultiText(area, textList, arg) - 多关键词点击
 *   findText(area, text, arg)  - 查找文字位置
 *   getPoint(area, text, arg)  - 获取文字坐标 {x, y}
 *   getPoints(area, text, arg) - 获取所有匹配坐标数组
 *   setModel(model)          - 切换当前模型档位(tiny/small/medium)
 *   loadModels(list)         - 预加载多个模型并常驻，返回加载结果数组
 *   getModels()              - 查看已登记的模型数组(序号即下标+1)
 *   setReleaseOthers(on)     - 单模型模式开关(默认 true=只保留当前模型,省内存；false=允许多模型常驻)，走 HTTP /config 接口
 *   getReleaseOthers()       - 读取单模型模式开关状态
 *   ping()                   - 检查服务是否可用
 *   appOps(pkg, op, mode)    - 跨应用 AppOps 读写（省略 mode=读当前模式；否则=设模式 allow/ignore/deny/default）
 *   grantPermission(pkg, perm) - 授予某包运行时权限（pm grant）
 *   revokePermission(pkg, perm) - 吊销某包运行时权限（pm revoke）
 *   setAppOp(pkg, op, mode)  - 设置某包 AppOps 模式
 *   getAppOp(pkg, op)        - 读取某包 AppOps 当前模式（返回对象含 .mode）
 *   listAppOps()             - 列出全部可控 AppOps 与通道/可用模式
 *
 */

// ==================== 配置区域 ====================
const host = '127.0.0.1';  // 地址: 一般填这个就行
const port = 9530;         // 端口
const type = 'high';       // 精度: high(高精度) / low(低精度)
const model = 'tiny';      // 当前模型档位: tiny(最快,默认) / small(更准) / medium(最高精度)
const models = ['tiny', 'small', 'medium,low']; // 序号映射: 1=第一个 2=第二个 3=第三个；元素写 'model' 或 'model,type' 简写精度，如 'medium,low'
const releaseOthers = true; // 卸载模型开关（单模型模式）: true=切换模型时自动卸载其它模型、只保留当前(默认,省内存) / false=允许多模型同时常驻

// 卸载开关（单模型模式）：默认开启 true=只保留当前模型，false=允许多模型常驻
// 主通道走 HTTP /config 接口的 single_model 字段；sd 卡标记文件仅作旧版兜底（只能强制开启）
const REL_FLAG = '/sdcard/.ocr_release_others';
// 1x1 预热图，仅用于触发引擎加载
const WARM_IMG = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==';

// ==================== SDK 实现 ====================
const OcrSdk = {
  host: host,
  port: port,
  type: type,
  model: model,
  models: models,

  /**
   * 初始化配置
   * @param {object} config - {host, port, type, model, models, releaseOthers}
   *        models 传数组(元素写 'model' 或 'model,type' 简写，或完整 {model,type} 对象) 时自动预加载并常驻，例如 {models:['tiny','small','medium,low']} 或 {models:['tiny','small',{model:'medium',type:'high'}]}
   */
  init: function(config) {
    if (config && config.host) this.host = config.host;
    if (config && config.port) this.port = config.port;
    if (config && config.type) this.type = config.type;
    if (config && config.model) this.model = this.normModel(config.model); // 当前模型档位
    // 卸载模型开关（单模型模式）：优先用 init 传入，否则用配置区域默认 releaseOthers
    let releaseFlag = (typeof (config && config.releaseOthers) === 'boolean') ? config.releaseOthers : releaseOthers;
    this.setReleaseOthers(releaseFlag);
    // 归一化 models（支持字符串数组 或 {model,type} 数组），每个元素登记为 {model, type}
    if (config && config.models && config.models.length) {
      this.loadModels(config.models); // 传入模型数组 → 预加载多个模型
    } else {
      this.models = [];
      for (let i = 0; i < models.length; i++) this.models.push(this.normModelEntry(models[i]));
    }
    return this;
  },

  /** 获取OCR服务地址 */
  getUrl: function() {
    return 'http://' + this.host + ':' + this.port + '/ocr';
  },

  /**
   * 模型名归一化
   * @param {string} m
   * @returns {string} 'tiny' | 'small' | 'medium'
   */
  normModel: function(m) {
    return (m === 'medium' || m === 'm' || m === 'v6_medium' || m === 'v6medium') ? 'medium'
         : (m === 'small' || m === 's' || m === 'v6_small' || m === 'v6small') ? 'small'
         : 'tiny';
  },

  /**
   * 把 models 的单个元素归一化为 {model, type}
   * 支持三种写法（自动解析）:
   *   字符串 'tiny'                    → { model:'tiny', type: undefined }（精度走默认 this.type）
   *   简写   'tiny,low'                → { model:'tiny', type:'low' }（逗号后=精度，自动拆分）
   *   对象   {model:'tiny',type:'low'} → { model:'tiny', type:'low' }（完整写法）
   * @param {string|object} entry
   * @returns {{model:string, type:?string}}
   */
  normModelEntry: function(entry) {
    if (entry && typeof entry === 'object') {
      return { model: this.normModel(entry.model), type: entry.type ? entry.type : undefined };
    }
    // 字符串支持 'model' 或 'model,type' 简写，逗号后=精度，例如 'medium,low'
    if (typeof entry === 'string') {
      let parts = entry.split(',');
      let m = parts[0].trim();
      let t = (parts.length > 1 && parts[1].trim()) ? parts[1].trim() : undefined;
      return { model: this.normModel(m), type: t };
    }
    return { model: this.normModel(entry), type: undefined };
  },

  /**
   * 把第二个参数归一化成 options 对象
   * 支持: 数字序号(1/2/3) | 模型名字符串 | options对象 | 不传
   */
  normOptions: function(arg) {
    if (arg === undefined || arg === null) return null;
    if (typeof arg === 'number') {
      let entry = this.models[Math.floor(arg) - 1];  // 1 → 第一个模型
      return entry ? { model: entry.model, type: entry.type } : null; // 带上该模型配置的精度；未配置则 undefined→走默认 this.type
    }
    if (typeof arg === 'string') {
      let mm = this.normModel(arg);
      let entry = null;
      for (let i = 0; i < this.models.length; i++) {
        if (this.models[i].model === mm) { entry = this.models[i]; break; }
      }
      return { model: mm, type: entry ? entry.type : undefined }; // 命中 models 中已配置精度则带上
    }
    return arg; // 已是 options 对象，原样透传
  },

  /**
   * 切换当前模型档位（全局生效）
   * @param {string|number} m - 'tiny'|'small'|'medium'，或模型数组序号
   * @returns {object} this
   */
  setModel: function(m) {
    if (typeof m === 'number') {
      let entry = this.models[Math.floor(m) - 1];
      if (entry) this.model = entry.model;
      return this;
    }
    this.model = this.normModel(m);
    return this;
  },

  /**
   * 预加载多个模型并常驻内存
   * @param {Array<string|object>} list - 元素为字符串或 {model,type}，例如 ['tiny','small','medium'] 或 [{model:'medium',type:'high'}]，不传则用当前 models
   * @returns {Array<{index:number, model:string, ok:boolean}>} 各模型加载结果
   */
  loadModels: function(list) {
    let src = (list && list.length) ? list : models;
    let entries = [];
    for (let i = 0; i < src.length; i++) entries.push(this.normModelEntry(src[i]));
    this.models = entries;
    this.setReleaseOthers(false); // 多模型常驻与"卸载其他引擎"互斥，这里强制关闭
    let res = [];
    for (let i = 0; i < this.models.length; i++) {
      let e = this.models[i];
      res.push({ index: i + 1, model: e.model, type: e.type || this.type, ok: this.warmUp(e.model) });
    }
    return res;
  },

  /** 查看已登记的模型数组（序号 = 下标 + 1），元素为 {model, type}（type 缺省表示该模型走默认精度 this.type） */
  getModels: function() {
    return this.models;
  },

  /**
   * 预热单个模型（发一张 1x1 图触发引擎加载）
   * @param {string} m
   * @returns {boolean}
   */
  warmUp: function(m) {
    try {
      let r = zdjl.requestUrl({
        url: this.getUrl(),
        method: 'POST',
        headers: [{ 'Content-Type': 'application/json' }],
        requestBody: JSON.stringify({ image: WARM_IMG, model: this.normModel(m), type: 'low' }),
        requestType: 'TEXT',
        responseType: 'TEXT'
      });
      return r.code === 200;
    } catch (e) {
      return false;
    }
  },

  /**
   * 单模型模式开关
   * @param {boolean} on - true=切换模型时自动卸载其它模型、只保留当前模型(默认,省内存) / false=允许多模型同时常驻
   * @returns {boolean} 是否设置成功
   */
  setReleaseOthers: function(on) {
    try {
      let r = zdjl.requestUrl({
        url: 'http://' + this.host + ':' + this.port + '/config',
        method: 'POST',
        headers: [{ 'Content-Type': 'application/json' }],
        requestBody: JSON.stringify({ single_model: !!on }),
        requestType: 'TEXT',
        responseType: 'TEXT'
      });
      if (r.code === 200) return true;
    } catch (e) {}
    try {
      let f = new java.io.File(REL_FLAG);
      if (on) {
        if (!f.exists()) {
          let os = new java.io.FileOutputStream(f);
          os.write(49); // 写入字符 '1'
          os.close();
        }
      } else if (f.exists()) {
        f['delete']();
      }
      return true;
    } catch (e) {
      return false;
    }
  },

  /** 读取单模型模式开关当前状态 */
  getReleaseOthers: function() {
    try {
      let r = zdjl.requestUrl({
        url: 'http://' + this.host + ':' + this.port + '/config',
        method: 'GET',
        headers: [],
        requestBody: '',
        requestType: 'TEXT',
        responseType: 'TEXT'
      });
      if (r.code === 200) {
        let json = JSON.parse(r.body);
        if (typeof json.single_model === 'boolean') return json.single_model;
      }
    } catch (e) {}
    try {
      return new java.io.File(REL_FLAG).exists();
    } catch (e) {
      return false;
    }
  },

  /** 截取屏幕区域 */
  captureScreen: function(area) {
    return zdjl.recognitionScreen({
      recognitionArea: area,
      recognitionMode: 'get_image_data',
      ocrResultType: 'text',
      humanRecMaxPositionCount: 1
    });
  },

  /**
   * OCR识别
   * @param {屏幕区域|string} area - 屏幕区域对象或Base64字符串
   * @param {number|string|object} arg - 模型序号(1/2/3) | 模型名 | {whitelist, boxes, color, type, model}
   *        不传则使用当前模型 this.model
   * @returns {{data: Array<{text: string, point: {x: number, y: number}, box: Array}>, timeout: number, model: string}}
   */
  ocr: function(area, arg) {
    let options = this.normOptions(arg);
    let startTime = Date.now();
    let base64;
    let offsetX = 0, offsetY = 0;

    if (typeof area === 'string') {
      base64 = area;
    } else {
      let screen = this.captureScreen(area);
      base64 = screen.base64;
      // 记录区域左上角偏移量
      offsetX = area.left || 0;
      offsetY = area.top || 0;
    }

    let body = { image: base64 };
    body.type = (options && options.type) || this.type;
    body.model = (options && options.model) || this.model; // 模型档位透传
    if (options && options.whitelist) body.whitelist = options.whitelist;
    if (options && options.boxes) body.boxes = options.boxes;
    if (options && options.color) body.color = options.color;

    let result = zdjl.requestUrl({
      url: this.getUrl(),
      method: 'POST',
      headers: [{ 'Content-Type': 'application/json' }],
      requestBody: JSON.stringify(body),
      requestType: 'TEXT',
      responseType: 'TEXT'
    });

    let timeout = Date.now() - startTime;

    if (result.code === 200) {
      try {
        let json = JSON.parse(result.body);
        let lines = json.data || json.lines || [];
        let data = [];
        for (let i = 0; i < lines.length; i++) {
          let line = lines[i];
          let box = line.box || [];
          let x = 0, y = 0;
          if (box.length >= 4) {
            if (Array.isArray(box[0])) {
              x = Math.round((box[0][0] + box[2][0]) / 2);
              y = Math.round((box[0][1] + box[2][1]) / 2);
            } else {
              x = Math.round((box[0] + box[2]) / 2);
              y = Math.round((box[1] + box[3]) / 2);
            }
          }
          // 加上区域左上角偏移，转换为屏幕绝对坐标
          data.push({
            text: line.text || '',
            point: { x: x + offsetX, y: y + offsetY },
            box: box,
            offset: { x: offsetX, y: offsetY }
          });
        }
        return {
          data: data,
          timeout: timeout,
          model: json.model || body.model,
          offset: { x: offsetX, y: offsetY }
        };
      } catch (e) {
        return { data: [], timeout: timeout, model: body.model, offset: { x: offsetX, y: offsetY } };
      }
    }
    return { data: [], timeout: timeout, model: body.model, offset: { x: offsetX, y: offsetY } };
  },

  /**
   * 是否出现文字
   * @param {屏幕区域|string} area - 屏幕区域对象或Base64字符串
   * @param {string} text - 要查找的文字
   * @param {number|string|object} arg - 模型序号 / 模型名 / 可选参数
   * @returns {boolean}
   */
  hasText: function(area, text, arg) {
    let result = this.ocr(area, arg);
    for (let i = 0; i < result.data.length; i++) {
      if (result.data[i].text.indexOf(text) !== -1) {
        return true;
      }
    }
    return false;
  },

  /**
   * 计算子字符串在文字框中的精确位置
   * @param {object} item - OCR结果项 {text, box}
   * @param {string} subText - 要查找的子字符串
   * @returns {{x: number, y: number}|null}
   */
  calcSubTextPoint: function(item, subText) {
    let fullText = item.text || '';
    let box = item.box || [];
    let offset = item.offset || { x: 0, y: 0 };
    let index = fullText.indexOf(subText);
    if (index === -1) return null;

    let totalLen = fullText.length;
    if (totalLen === 0) return null;

    // 计算子字符串的起始和结束位置比例
    let startRatio = index / totalLen;
    let endRatio = (index + subText.length) / totalLen;
    let centerRatio = (startRatio + endRatio) / 2;

    let left, right, top, bottom;

    if (box.length >= 4) {
      if (Array.isArray(box[0])) {
        // [[x1,y1], [x2,y2], [x3,y3], [x4,y4]] 格式
        left = box[0][0];
        right = box[2][0];
        top = box[0][1];
        bottom = box[2][1];
      } else {
        // [left, top, right, bottom] 格式
        left = box[0];
        top = box[1];
        right = box[2];
        bottom = box[3];
      }

      // 按比例计算X坐标，加上区域偏移
      let x = Math.round(left + (right - left) * centerRatio) + offset.x;
      let y = Math.round((top + bottom) / 2) + offset.y;

      return { x: x, y: y };
    }

    return item.point;
  },

  /**
   * 查找文字位置（精确到子字符串位置）
   * @param {屏幕区域|string} area - 屏幕区域对象或Base64字符串
   * @param {string} text - 要查找的文字
   * @param {number|string|object} arg - 模型序号 / 模型名 / 可选参数
   * @returns {{x: number, y: number}|null}
   */
  findText: function(area, text, arg) {
    let result = this.ocr(area, arg);
    for (let i = 0; i < result.data.length; i++) {
      let item = result.data[i];
      if (item.text.indexOf(text) !== -1) {
        // 计算子字符串的精确位置
        return this.calcSubTextPoint(item, text);
      }
    }
    return null;
  },

  /**
   * 获取文字坐标
   * @param {屏幕区域|string} area - 屏幕区域对象或Base64字符串
   * @param {string} text - 要查找的文字
   * @param {number|string|object} arg - 模型序号 / 模型名 / 可选参数
   * @returns {{x: number, y: number}} 未找到返回 {x: -1, y: -1}
   */
  getPoint: function(area, text, arg) {
    let point = this.findText(area, text, arg);
    return point || { x: -1, y: -1 };
  },

  /**
   * 获取所有匹配文字的坐标数组
   * @param {屏幕区域|string} area - 屏幕区域对象或Base64字符串
   * @param {string} text - 要查找的文字
   * @param {number|string|object} arg - 模型序号 / 模型名 / 可选参数
   * @returns {Array<{x: number, y: number}>}
   */
  getPoints: function(area, text, arg) {
    let result = this.ocr(area, arg);
    let points = [];
    for (let i = 0; i < result.data.length; i++) {
      let item = result.data[i];
      if (item.text.indexOf(text) !== -1) {
        let point = this.calcSubTextPoint(item, text);
        if (point) {
          points.push(point);
        }
      }
    }
    return points;
  },

  /**
   * 点击文字（精确到子字符串位置）
   * @param {屏幕区域|string} area - 屏幕区域对象或Base64字符串
   * @param {string} text - 要点击的文字
   * @param {number|string|object} arg - 模型序号 / 模型名 / 可选参数
   * @returns {boolean} 是否点击成功
   */
  clickText: function(area, text, arg) {
    let point = this.findText(area, text, arg);
    if (point && point.x > 0 && point.y > 0) {
      zdjl.click(point.x, point.y);
      return true;
    }
    return false;
  },

  /**
   * 多关键词点击，仅单次OCR识别
   * @param {屏幕区域|string} area - 识别区域
   * @param {Array<string>} textList - 关键词数组 ["X","x","×"]
   * @param {number|string|object} arg - 模型序号 / 模型名 / 可选参数
   * @returns {boolean} 是否成功点击
   */
  clickMultiText: function(area, textList, arg) {
    let result = this.ocr(area, arg);
    for (let i = 0; i < result.data.length; i++) {
      let item = result.data[i];
      for (let keyword of textList) {
        if (item.text.indexOf(keyword) !== -1) {
          let point = this.calcSubTextPoint(item, keyword);
          if (point && point.x > 0 && point.y > 0) {
            zdjl.click(point.x, point.y);
            return true;
          }
        }
      }
    }
    return false;
  },

  /**
   * 阻塞睡眠（同步，会卡死自动精灵单线程 JS 引擎）。
   * ★ 除非你完全确定知道后果，否则不要在主链路调用！轮询请用 zdjl.sleepAsync + await。
   * 仅在某些初始化等不需要响应其他事件的场景里偶尔可用。
   */
  sleep: function(ms) {
    try { if (typeof zdjl.sleep === 'function') { zdjl.sleep(ms); return; } } catch (e) {}
    try { java.lang.Thread.sleep(ms); } catch (e) {}
  },

  /** 内部：通用 HTTP POST（Web 窗口用）。返回原始响应对象 r（含 code/body），失败 null。 */
  _httpPost: function(path, body) {
    try {
      return zdjl.requestUrl({
        url: 'http://' + this.host + ':' + this.port + path,
        method: 'POST',
        headers: [{ 'Content-Type': 'application/json' }],
        requestBody: JSON.stringify(body || {}),
        requestType: 'TEXT',
        responseType: 'TEXT'
      });
    } catch (e) { return null; }
  },

  /** 内部：把 HTTP 原始响应解析为 JSON 对象；非 200 / 无 body / 解析失败返回 null。 */
  _parse: function(r) {
    if (r && r.code === 200 && r.body) { try { return JSON.parse(r.body); } catch (e) {} }
    return null;
  },

  /** 检查OCR服务是否可用 */
  ping: function() {
    try {
      let result = zdjl.requestUrl({
        url: 'http://' + this.host + ':' + this.port + '/',
        method: 'GET',
        headers: [],
        requestBody: '',
        requestType: 'TEXT',
        responseType: 'TEXT'
      });
      return result.code === 200;
    } catch (e) {
      return false;
    }
  },

  // ==================== 跨应用权限管理（对接 /manage_permission + /list_appops） ====================
  // 前置：设备已授予本插件 root 或 Shizuku 通道（权限页手动「请求」）。仅管理「其他应用」权限。

  /** 列出全部可控 AppOps（{op, perm, desc}）+ 当前通道/可用模式。返回 /list_appops 解析对象；失败 null。 */
  listAppOps: function() {
    try {
      let r = zdjl.requestUrl({
        url: 'http://' + this.host + ':' + this.port + '/list_appops',
        method: 'GET', headers: [], requestBody: '', requestType: 'TEXT', responseType: 'TEXT'
      });
      if (r && r.code === 200 && r.body) return JSON.parse(r.body);
    } catch (e) {}
    return null;
  },

  /** 内部：POST /manage_permission。body={action,pkg,perm?,op?,mode?}。返回解析响应对象；失败 null。 */
  _manage: function(action, pkg, perm, op, mode) {
    let body = { action: action, pkg: pkg };
    if (perm) body.perm = perm;
    if (op) body.op = op;
    if (mode) body.mode = mode;
    return this._parse(this._httpPost('/manage_permission', body));
  },

  /** 授予某包运行时权限（pm grant）。perm=权限全名如 'android.permission.READ_CONTACTS'。返回 {success,channel,code,stdout,stderr,message}；失败 null。 */
  grantPermission: function(pkg, perm) {
    return this._manage('grant', pkg, perm, null, null);
  },

  /** 吊销某包运行时权限（pm revoke）。返回同上结构。 */
  revokePermission: function(pkg, perm) {
    return this._manage('revoke', pkg, perm, null, null);
  },

  /** 设置某包某 AppOps 模式（appops set）。op=AppOps 名如 'READ_CONTACTS'；mode∈allow|ignore|deny|default。返回同上结构。 */
  setAppOp: function(pkg, op, mode) {
    return this._manage('set_appop', pkg, op, null, mode);
  },

  /** 读取某包某 AppOps 当前模式（appops get）。op=AppOps 名。返回解析对象并额外补 .mode 字段；失败 null。 */
  getAppOp: function(pkg, op) {
    let r = this._manage('get_appop', pkg, null, op, null);
    if (r && r.stdout) {
      // stdout ≈ "READ_CONTACTS: allow" 或 "Uid mode: READ_CONTACTS: allow"
      let idx = r.stdout.lastIndexOf(':');
      if (idx > 0) r.mode = r.stdout.substring(idx + 1).split(';')[0].trim();
    }
    return r;
  },

  /**
   * 统一 AppOps 读写入口（对应 /manage_permission）：
   *   appOps(pkg, op)        → 读当前模式（等价 getAppOp，返回对象含 .mode）
   *   appOps(pkg, op, mode)  → 设模式（等价 setAppOp，mode∈allow|ignore|deny|default）
   * @returns {object|null} /manage_permission 响应（success/channel/code/stdout/stderr/message；getter 多一个 .mode）
   */
  appOps: function(pkg, op, mode) {
    if (mode === undefined || mode === null || mode === '') return this.getAppOp(pkg, op);
    return this.setAppOp(pkg, op, mode);
  }
};

// ==================== 初始化并导出 ====================
// 只用单个模型: OcrSdk.init()
// 多模型常驻(简写精度):   OcrSdk.init({ models: ['tiny', 'small', 'medium,low'] })
OcrSdk.init();  // 写入字段到 OcrSdk 自身

// 导出为自动精灵「全局变量」（与 ocr 原导出方式一致），后续步骤/变量面板均可访问。
zdjl.setVar("ocr", OcrSdk, "global");

// ==================== 简洁调用：按OCR行原样返回 ====================
function OcrTextOnly(area, modelName) {
  try {
    var r = OcrSdk.ocr(area, {model: modelName || "small", type: "high"});
    if (!r || !r.data) return "";
    var arr = [];
    for (var i = 0; i < r.data.length; i++) {
      if (r.data[i] && r.data[i].text) arr.push(String(r.data[i].text).trim());
    }
    return arr.join("\r\n").trim();
  } catch (e) {
    return "";
  }
