{"type":"运行JS代码","delay":"0","delayUnit":1,"repeatCount":1,"desc":"统一农场记录TXT + 共用待传队列 + 自己农场OCR原文上传","jsCode":"var FARM_API="http://38.207.187.183:8787/api/farm-records";
var FARM_TOKEN="1f217af4efb810576fec17e1c974f9436f84e72b6cfdbb5120a75a2bdcb0cd43";
var FARM_TXT="/sdcard/Download/农场记录.txt";
var FARM_QUEUE="/sdcard/Download/农场待上传.jsonl";
var MUT_TXT="/sdcard/Download/变异植物记录.txt";
var TIMEOUT=5000;
var BATCH=20;

function G(k,d){
    try{
        var v=zdjl.getVar(k,"global");
        return (v===undefined || v===null || v==="") ? d : v;
    }catch(e){return d;}
}
function P(n){return ("0"+n).slice(-2);}

var d=new Date();
var time=d.getFullYear()+"-"+P(d.getMonth()+1)+"-"+P(d.getDate())+" "+P(d.getHours())+":"+P(d.getMinutes())+":"+P(d.getSeconds());

// 软件账号归属只看脚本OCR得到的原始文字。脚本不生成账号名/身份键，也不使用HUD名称猜测。
var farmOcr=String(G("自己农场OCR原文","")).replace(/\r\n?/g,"\n").trim();

var area=Number(G("当前区",0))||0;
var total=Number(G("总数区",0))||0;
var cnt=Number(G("变异本区数量",0))||0;
var details=String(G("变异本区记录","")).trim();

// 无效区号只写专项调试记录，不进入统一农场记录，也不上云。
// 例如手动测试子脚本时遗留的 11/10。
if(area<1 || total<1 || area>total){
    var bad="[变异汇总跳过正式上传] "+time+"｜区号="+area+"/"+total+"｜数量="+cnt+"\r\n";
    try{zdjl.appendFile(MUT_TXT,bad);}catch(e){}
    try{zdjl.toast("变异记录区号无效 "+area+"/"+total+"｜未上传",1800);}catch(e){}
    return;
}

var record=
    "===== 变异植物汇总 =====\r\n"+
    "记录类型：变异植物汇总\r\n"+
    "记录时间："+time+"\r\n"+
    "【自己农场OCR】\r\n"+(farmOcr||"未识别")+"\r\n\r\n"+
    "区："+area+"/"+total+"\r\n"+
    "数量："+cnt+"\r\n"+
    "明细：\r\n"+(details||"无")+"\r\n"+
    "==============================\r\n\r\n";

// 主数据源统一进入农场记录；变异专用TXT只保留调试备份。
try{zdjl.appendFile(FARM_TXT,record);}catch(e){}
try{zdjl.appendFile(MUT_TXT,record);}catch(e){}
try{zdjl.appendFile(FARM_QUEUE,JSON.stringify({record:record})+"\n");}catch(e){}

try{
    var lines=String(zdjl.readFile(FARM_QUEUE)||"").split(/\r?\n/);
    var pending=[];
    for(var i=0;i<lines.length;i++) if(lines[i]) pending.push(lines[i]);

    var done=0;
    while(done<pending.length && done<BATCH){
        var item;
        try{ item=JSON.parse(pending[done]); }
        catch(e){ done++; continue; }

        var resp;
        try{
            resp=zdjl.requestUrl({
                url:FARM_API,
                method:"POST",
                timeout:TIMEOUT,
                headers:[
                    {"Content-Type":"application/json"},
                    {"X-Farm-Token":FARM_TOKEN}
                ],
                requestBody:JSON.stringify({record:item.record}),
                requestType:"TEXT",
                responseType:"TEXT"
            });
        }catch(e){ break; }

        if(!resp || resp.code!==200) break;
        var ok=false;
        try{ok=!!JSON.parse(resp.body||"{}").ok;}catch(e){ok=false;}
        if(!ok) break;
        done++;
    }

    if(done){
        var remain=pending.slice(done).join("\n");
        zdjl.writeFile(FARM_QUEUE,remain+(remain?"\n":""));
    }
}catch(e){}"}

