(function(){
    // 先检查Root守护本身是否活着，避免守护已经卡死时白等25秒才报“绑定失败”。
    var __guardHealthPath="/sdcard/Download/农场守护心跳.txt";
    var __guardHealth="";
    try{__guardHealth=String(zdjl.readFile(__guardHealthPath)||"");}catch(__ghReadErr){__guardHealth="";}
    function __ghGet(k){
        var m=new RegExp("(?:^|\\n)"+k+"=([^\\r\\n]*)").exec(__guardHealth);
        return m?String(m[1]||""):"";
    }
    var __ghEpoch=Number(__ghGet("epoch"))||0;
    var __ghVersion=__ghGet("version")||"?";
    var __ghAge=__ghEpoch>0 ? Math.floor(Date.now()/1000)-__ghEpoch : 999999;
    if(__ghAge<0) __ghAge=999999;
    if(!__ghEpoch || __ghAge>35){
        var __ghText="Root守护心跳失效（version="+__ghVersion+"，age="+__ghAge+"s）。请先确认Magisk守护正常运行/重启模拟器。";
        try{
            zdjl.runAction({
                "type":"系统提示","delay":"0","delayUnit":1,"repeatCount":1,
                "promptType":"notification","promptTitle":"王者绑定前检查失败",
                "promptText":__ghText,
                "showPosition":"default","playAudio":"false","useVibrator":false
            });
        }catch(__ghNotifyErr){}
        try{zdjl.toast(__ghText,6000);}catch(__ghToastErr){}
        try{zdjl.runAction({"type":"控制执行","delay":"0","delayUnit":1,"controlRunType":"stop","jumpToPosition":"","ContinueParentExecute":false});}catch(__ghStopErr){}
        throw new Error(__ghText);
    }

    var __bindTask=String(Date.now());
    var __bindReq="/sdcard/Download/王者绑定请求.txt";
    var __bindState="/sdcard/Download/当前王者绑定.txt";
    var __bindAck="/sdcard/Download/王者绑定已接收.txt";
    try{zdjl.setVar("王者绑定任务ID",__bindTask,"global");}catch(e){}
    try{
        zdjl.setVar("王者绑定用户","","global");
        zdjl.setVar("王者绑定包名","","global");
        zdjl.setVar("王者绑定Activity","","global");
    }catch(e2){}

    var __attempt=0;
    var __lastWrite=0;
    function __writeBindRequest(){
        __attempt++;
        __lastWrite=Date.now();
        try{
            zdjl.writeFile(__bindReq,
                "task="+__bindTask+"\n"+
                "request_epoch="+Date.now()+"\n"+
                "attempt="+__attempt+"\n"
            );
            return true;
        }catch(__w){return false;}
    }
    __writeBindRequest();
    try{zdjl.toast("正在绑定本轮王者实例…",2500);}catch(__bindToastErr){}

    // Root收到请求后会先写“已接收”，再删除请求；如果没收到，总控每2秒重发一次。
    // 这样即使恰好撞上文件正在写入的瞬间，也不会把本轮请求永久吃掉。
    var __deadline=Date.now()+25000;
    var __state="";
    var __ack="";
    var __received=false;
    var __ok=false;
    while(Date.now()<__deadline){
        try{__state=String(zdjl.readFile(__bindState)||"");}catch(__readBindErr){__state="";}
        if(__state.indexOf("task="+__bindTask+"\n")>=0 && __state.indexOf("status=bound")>=0){
            __ok=true;
            break;
        }

        try{__ack=String(zdjl.readFile(__bindAck)||"");}catch(__ackErr){__ack="";}
        __received=(__ack.indexOf("task="+__bindTask+"\n")>=0 && __ack.indexOf("status=received")>=0);
        // 即使已经收到ACK，只要还没真正bound，也继续低频重发。
        // 这样Root若恰好在ACK之后被supervisor重启，新守护仍能重新拾取本轮请求。
        var __retryGap=__received?4000:2000;
        if(Date.now()-__lastWrite>=__retryGap){
            __writeBindRequest();
        }
        zdjl.sleep(500);
    }

    if(!__ok){
        var __reqLeft="";
        try{__reqLeft=String(zdjl.readFile(__bindReq)||"");}catch(__reqLeftErr){__reqLeft="";}
        var __reqStill=(__reqLeft.indexOf("task="+__bindTask+"\n")>=0);
        var __failText="";
        if(__received){
            __failText="Root守护已收到绑定请求，但25秒内没有识别到前台王者。请查看 王者守护调试.txt。";
        }else{
            __failText="Root守护没有完成本轮握手。v1.5已自动重发"+__attempt+"次，请查看 王者守护调试.txt。";
