function __arr(r){
    if(!r) return [];
    if(Object.prototype.toString.call(r)==='[object Array]') return r;
    return [r];
}
function __all(tpl){
    var out=[];
    try{
        var r=zdjl.findLocation(tpl,true);
        out=__arr(r);
        if(out.length>1) return out;
    }catch(e){}
    // 兼容部分版本：若 findLocation(..., true) 没有返回多结果，
    // 再用 indexNum 逐个取第1～20个匹配。
    var seen=[];
    for(var i=1;i<=20;i++){
        try{
            var q={};
            for(var k in tpl) q[k]=tpl[k];
            q.indexNum=String(i);
            var one=zdjl.findLocation(q);
            if(!one) break;
            var p=__xy(one);
            if(!p) break;
            var dup=false;
            for(var d=0;d<seen.length;d++){
                if(Math.abs(seen[d].x-p.x)<5 && Math.abs(seen[d].y-p.y)<5){dup=true;break;}
            }
            if(dup){
                if(i>=2) break;
            }else{
                seen.push(p);
            }
        }catch(e2){break;}
    }
    if(seen.length>out.length) return seen;
    return out;
}
function __xy(p){
    if(!p) return null;
    var x=Number(p.x), y=Number(p.y);
    if(!isFinite(x) || !isFinite(y)) return null;
    return {x:x,y:y};
}
function __detectRows(){
    var raw=[];
    var a=__all(__RED), b=__all(__GREEN), c=__all(__GRAY);
    var src=[a,b,c];
    for(var si=0;si<src.length;si++){
        for(var i=0;i<src[si].length;i++){
            var q=__xy(src[si][i]);
            if(!q) continue;
            // 只取右侧服务器列表；排除顶部“上次登录”和右上角状态图例。
            if(q.x<145 || q.x>1270 || q.y<140 || q.y>710) continue;
            var dup=false;
            for(var d=0;d<raw.length;d++){
                if(Math.abs(raw[d].x-q.x)<14 && Math.abs(raw[d].y-q.y)<14){dup=true;break;}
            }
            if(!dup) raw.push(q);
        }
    }
    raw.sort(function(p1,p2){return p1.y-p2.y || p1.x-p2.x;});
    var rows=[];
    for(var r=0;r<raw.length;r++){
        var p=raw[r], row=null;
        for(var k=0;k<rows.length;k++){
            if(Math.abs(rows[k].y-p.y)<=18){row=rows[k];break;}
        }
        if(!row){
            row={y:p.y,pts:[]};
            rows.push(row);
        }
        row.pts.push(p);
        var sum=0;
        for(var z=0;z<row.pts.length;z++) sum+=row.pts[z].y;
        row.y=sum/row.pts.length;
    }
    rows.sort(function(r1,r2){return r1.y-r2.y;});
    for(var m=0;m<rows.length;m++){
        rows[m].pts.sort(function(p1,p2){return p1.x-p2.x;});
    }
    // 网格合理性：相邻行中心距正常约92px，允许滚动中有轻微透视/裁切。
    if(rows.length>=2){
        for(var n=1;n<rows.length;n++){
            var gap=rows[n].y-rows[n-1].y;
            if(gap<65 || gap>120){
                return [];
            }
        }
    }
    return rows;
}
function __detectStable(){
    var best=[];
    for(var t=0;t<4;t++){
        var r=__detectRows();
        if(r.length>best.length) best=r;
        if(r.length>=3) return r;
        zdjl.sleep(120);
    }
    return best;
}
function __pickPoint(row,right){
    if(!row || !row.pts) return null;
    var mid=640;
    var best=null;
    for(var i=0;i<row.pts.length;i++){
        var p=row.pts[i];
        if(right){
            if(p.x>mid && (!best || p.x<best.x)) best=p;
        }else{
            if(p.x<mid && (!best || p.x>best.x)) best=p;
        }
    }
    return best;
}
