        for(var __step=0;__step<__maxSteps;__step++){
            var __idx=__targetRow-__firstLogicalRow;
            if(__idx>=0&&__idx<__rows.length){
                var __row=__rows[__idx];
                if(__row.y>=150&&__row.y<=685){
