function __槽任务(i){
    if(i==1) return String(任务1||"无");
    if(i==2) return String(任务2||"无");
    if(i==3) return String(任务3||"无");
    return "无";
}
function __任务转做啥(t){
    if(t=="浇水") return "只浇水";
    if(t=="祝福") return "祝福";
    if(t=="收割") return "收割";
    if(t=="1V1") return "打11";
    if(t=="55") return "打55";
    return "";
}
function __下一任务(i){
    for(var n=Number(i)+1;n<=3;n++) if(__槽任务(n)!="无") return n;
    return 0;
}

if(当前区>总数区){
    var __prev=__槽任务(当前任务序号);
    var __nextIndex=__下一任务(当前任务序号);

    if(__nextIndex>0){
        var __next=__槽任务(__nextIndex);
        if(__prev=="浇水" && __next=="祝福" && Number(浇祝间隔)>0){
            阶段需等待="是";
        }
        当前任务序号=__nextIndex;
        做啥=__任务转做啥(__next);
        阶段已切换="是";
        当前区=1;
        当前格=1;
        需要回顶="是";
