try{
    function __hf2(n){n=Number(n)||0;return n<10?("0"+n):String(n);}
    var __hms=Math.max(0,Date.now()-(Number(HUD启动时间)||Date.now()));
    var __hsec=Math.floor(__hms/1000);
    var __hh=Math.floor(__hsec/3600), __hm=Math.floor((__hsec%3600)/60), __hs=__hsec%60;
    var __htime=__hh>0 ? (__hh+":"+__hf2(__hm)+":"+__hf2(__hs)) : (__hf2(__hm)+":"+__hf2(__hs));
    var __hseq="";
    if(String(临时模式||"")!="是"){
        __hseq=String(账号序列||"").replace(/[^1-8]/g,"");
        if(!__hseq) __hseq=String(Number(当前第几个号)||"");
    }
    var __hname=String(HUD当前账号||"").trim()||"?";
    __hname=__hname.replace(/安卓$/i,"安").replace(/ios$/i,"i").replace(/vx$/i,"V");
    var __harea=(Number(当前区)||0)+"/"+(Number(总数区)||0);
    var __htask=String(HUD任务||"").trim()||"运行";
    if(__htask=="打11") __htask="11";
    else if(__htask=="打55") __htask="55";
    else if(__htask=="祝福") __htask="福";
    else if(__htask=="浇水") __htask="水";
    else if(__htask=="换英") __htask="英";
    else if(__htask=="换经") __htask="经";
    else if(__htask=="选区") __htask="选";
    else if(__htask=="切号") __htask="切";
    else if(__htask=="收尾") __htask="尾";
    else if(__htask=="准备") __htask="备";
    HUD文本=__htime+"｜"+(__hseq?__hseq+"｜":"")+__hname+"｜"+__harea+"｜"+__htask;
    zdjl.setVar("HUD文本",HUD文本,"global");
}catch(__hudLiteErr){}
