    var __sec=Math.floor((Number(HUD完成耗时)||0)/1000);
    var __hh=Math.floor(__sec/3600);
    var __mm=Math.floor((__sec%3600)/60);
    var __ss=__sec%60;
    function __p(n){return n<10?("0"+n):String(n);}
    var __seq=String(账号序列||"").replace(/[^1-8]/g,"");
    var __beh=String(HUD本次行为||"任务");
    HUD文本="✅ 完成｜"+(__hh>0?(__hh+":"+__p(__mm)+":"+__p(__ss)):(__p(__mm)+":"+__p(__ss)));
    zdjl.setVar("HUD文本",HUD文本,"global");
}catch(__hudEndErr){}
try{
    zdjl.writeFile("/sdcard/Download/农场8账号断点.txt",
        "V4|完成|"+当前第几个号+"|"+当前区+"|"+任务1+"|"+任务2+"|"+任务3+"|"+当前任务序号+"|"+账号序列+"|"+序列位置+"|"+总数区+"|"+(Number(浇祝间隔)||0)+"|"+特殊模式
    );
}catch(e){}
try{
    function __pn(k){try{return Number(zdjl.getVar(k,"global")||0)||0;}catch(e){return 0;}}
    function __fmtMs(ms){
        ms=Math.max(0,Number(ms)||0);
        var s=Math.floor(ms/1000),h=Math.floor(s/3600),m=Math.floor((s%3600)/60),ss=s%60;
        function p(n){return n<10?"0"+n:String(n);}
        return p(h)+":"+p(m)+":"+p(ss);
    }
    function __avg(tag){
        var n=__pn("PERF_"+tag+"_次数"),ms=__pn("PERF_"+tag+"_毫秒");
        return n>0?(ms/n/1000).toFixed(2)+"s×"+n:"-";
    }
    var __perfText=
        "性能仪表｜总耗时 "+__fmtMs(Number(HUD完成耗时)||0)+"\n"+
        "选区 "+__avg("选区")+"｜重试 "+__pn("PERF_选区重试")+"\n"+
        "进游戏 "+__avg("进游戏")+"｜浇水领奖 "+__avg("浇水领奖")+"\n"+
        "祝福 "+__avg("祝福")+"｜收割 "+__avg("收割")+"｜打11 "+__avg("打11")+"｜打55 "+__avg("打55")+"\n"+
        "状态审查 "+__avg("状态")+"｜退出 "+__avg("退出")+"｜切号 "+__avg("切号")+"\n"+
        "重启 "+__avg("重启")+"｜换作物 "+__avg("换作物");
    var __stamp=new Date();
    var __head=__stamp.getFullYear()+"-"+(__stamp.getMonth()+1)+"-"+__stamp.getDate()+" "+__stamp.getHours()+":"+__stamp.getMinutes()+":"+__stamp.getSeconds();
    zdjl.writeFile("/sdcard/Download/农场性能统计.txt",__head+"\n"+__perfText);
}catch(__perfEndErr){}
try{
    var __doneMs=Number(HUD完成耗时)||0;
    var __doneSec=Math.floor(__doneMs/1000);
    var __doneH=Math.floor(__doneSec/3600);
    var __doneM=Math.floor((__doneSec%3600)/60);
    var __doneS=__doneSec%60;
    function __doneP(n){return n<10?("0"+n):String(n);}
    var __doneTime=__doneH>0?(__doneH+":"+__doneP(__doneM)+":"+__doneP(__doneS)):(__doneP(__doneM)+":"+__doneP(__doneS));

    function __doneName(n){
        if(n==1) return String(账号1名称||"1号");
        if(n==2) return String(账号2名称||"2号");
        if(n==3) return String(账号3名称||"3号");
        if(n==4) return String(账号4名称||"4号");
        if(n==5) return String(账号5名称||"5号");
        if(n==6) return String(账号6名称||"6号");
        if(n==7) return String(账号7名称||"7号");
        if(n==8) return String(账号8名称||"8号");
        return "?";
    }
    function __doneAreas(n){
        if(n==1) return Number(账号1区数)||0;
        if(n==2) return Number(账号2区数)||0;
        if(n==3) return Number(账号3区数)||0;
        if(n==4) return Number(账号4区数)||0;
        if(n==5) return Number(账号5区数)||0;
        if(n==6) return Number(账号6区数)||0;
        if(n==7) return Number(账号7区数)||0;
        if(n==8) return Number(账号8区数)||0;
        return 0;
    }

    var __doneAccounts=[];
    if(String(临时模式||"")=="是"){
        __doneAccounts.push(String(临时账号名称||"?")+"("+(Number(总数区)||0)+"区)");
    }else{
        var __seqText=String(账号序列||"");
        var __seqArr=__seqText.match(/[1-8]/g)||[];
        if(__seqArr.length<1){
            var __curNo=Number(当前第几个号)||0;
            if(__curNo>=1 && __curNo<=8) __seqArr=[String(__curNo)];
        }
        for(var __di=0;__di<__seqArr.length;__di++){
            var __dn=Number(__seqArr[__di])||0;
            if(__dn>=1 && __dn<=8){
                __doneAccounts.push(__doneName(__dn)+"("+__doneAreas(__dn)+"区)");
            }
        }
    }

    var __doneTask=String(HUD本次行为||"任务").trim()||"任务";
    var __faultSmall=0,__faultBig=0;
    try{__faultSmall=Number(zdjl.getVar("容错小失败次数","global")||0)||0;}catch(e){}
    try{__faultBig=Number(zdjl.getVar("容错大失败次数","global")||0)||0;}catch(e){}
    var __doneText="✅ 农场任务全部完成｜耗时 "+__doneTime+
        "\n任务："+__doneTask+
        "\n账号："+(__doneAccounts.length?__doneAccounts.join("｜"):"?")+
        "\n小失败："+__faultSmall+"｜大失败："+__faultBig;
