var FARM_API = "http://38.207.187.183:8787/api/farm-records";
var FARM_TOKEN = "1f217af4efb810576fec17e1c974f9436f84e72b6cfdbb5120a75a2bdcb0cd43";
var FARM_TXT = "/sdcard/Download/农场记录.txt";
var FARM_QUEUE = "/sdcard/Download/农场待上传.jsonl";
var d = new Date();
var p = function(n){ return ("0" + n).slice(-2); };
var time = d.getFullYear() + "-" + p(d.getMonth()+1) + "-" + p(d.getDate()) + " " + p(d.getHours()) + ":" + p(d.getMinutes()) + ":" + p(d.getSeconds());
var record = "===== 记录时间：" + time + " =====\r\n" +
  "【植物状态】\r\n" + (植物状态内容 || "") + "\r\n\r\n" +
  "【每日任务】\r\n" + (每日任务内容 || "") + "\r\n\r\n" +
  "【等级经钱】\r\n" + (等级经钱内容 || "") + "\r\n" +
  "==============================\r\n\r\n";
zdjl.appendFile(FARM_TXT, record);
zdjl.appendFile(FARM_QUEUE, JSON.stringify({record:record}) + "\n");
try {
  var lines = String(zdjl.readFile(FARM_QUEUE) || "").split(/\r?\n/);
  var pending = [];
  for (var i=0; i<lines.length; i++) if (lines[i]) pending.push(lines[i]);
  var done = 0;
  while (done < pending.length && done < 20) {
    var item = JSON.parse(pending[done]);
    var response = zdjl.requestUrl({
      url:FARM_API, method:"POST",
      headers:[{"Content-Type":"application/json"},{"X-Farm-Token":FARM_TOKEN}],
      requestBody:JSON.stringify({record:item.record}),
      requestType:"TEXT", responseType:"TEXT"
    });
    if (!response || response.code !== 200 || !JSON.parse(response.body || "{}").ok) break;
    done++;
  }
  if (done) zdjl.writeFile(FARM_QUEUE, pending.slice(done).join("\n") + (done < pending.length ? "\n" : ""));
} catch (farmSyncError) {
  // 本地 TXT 与待传队列均已写入；下次扫描自动重试。
}
"}

