    function endsWithIgnoreCase(s, suffix) {
        s = String(s).toLowerCase();
        suffix = String(suffix).toLowerCase();
        return s.lastIndexOf(suffix) === s.length - suffix.length;
    }

    function isManagedZjs(name) {
        name = String(name);
        if (!endsWithIgnoreCase(name, ".zjs")) return false;
        for (var i = 0; i < EXCLUDE_PREFIXES.length; i++) {
            if (name.indexOf(EXCLUDE_PREFIXES[i]) === 0) return false;
        }
        return true;
    }

    function listByNodeFs(dir) {
        if (typeof require !== "function") return null;
        var fs = require("fs");
        if (!fs || typeof fs.readdirSync !== "function") return null;

        var names = fs.readdirSync(dir);
        var out = [];

        for (var i = 0; i < names.length; i++) {
            var n = String(names[i]);
            if (!isManagedZjs(n)) continue;

            try {
                var stat = fs.statSync(dir + n);
                if (!stat || typeof stat.isFile !== "function" || !stat.isFile()) continue;
            } catch (ignoreStat) {
                continue;
            }

            out.push(n);
        }

        return out;
    }

    function listByJavaFile(dir) {
        var FileClass = null;

        try {
            if (typeof Java !== "undefined" && Java && typeof Java.type === "function") {
                FileClass = Java.type("java.io.File");
            }
        } catch (ignoreJavaType) {}

        if (!FileClass) {
            try {
                if (typeof Packages !== "undefined" &&
                    Packages.java && Packages.java.io && Packages.java.io.File) {
                    FileClass = Packages.java.io.File;
                }
            } catch (ignorePackages) {}
        }

        if (!FileClass) return null;

        var folder = new FileClass(dir);
        var arr = folder.listFiles();
        if (arr == null) return [];

        var out = [];
        for (var i = 0; i < arr.length; i++) {
            var f = arr[i];
            try {
                if (!f.isFile()) continue;
                var n = String(f.getName());
                if (isManagedZjs(n)) out.push(n);
            } catch (ignoreOne) {}
