        return out;
    }

    function managedFileOrder(a, b) {
        a = String(a); b = String(b);
        function rank(n) {
            if (n === "农场脚本下载.zjs") return 3;
            if (n === "农场脚本版本更新器.zjs") return 2;
            if (n === "农场脚本版本发布器.zjs") return 1;
            return 0;
        }
        var ra = rank(a), rb = rank(b);
        if (ra !== rb) return ra - rb;
