        }

        var r = getRaw(CLOUD_DIR + name, release.snapshotSha);

        if (r.code === 404) return {status:"cloudMissing", name:name};
        if (r.code !== 200) return {status:"failed", name:name, detail:"HTTP " + r.code};

        var cloudText = String(r.body);
        var path = BASE_DIR + name;
        var oldText = localText(path);

        if (oldText !== null && oldText === cloudText) {
            if (doWrite) markInstalled(name, release);
            return {status:"same", name:name};
        }

        if (!doWrite) return {status:"different", name:name};

        if (oldText !== null) {
            try { zdjl.writeFile(backupName(name), oldText); } catch (ignoreBak) {}
