        try{t=trimText(zdjl.getStorage("github_token",NS));}catch(e3){}
        return looksLikeToken(t)?t:"";
    }
    function rawUrl(){return "https://raw.githubusercontent.com/"+encodeURIComponent(OWNER)+"/"+encodeURIComponent(REPO)+"/"+encodeURIComponent(BRANCH)+"/"+encodeRepoPath(PACKAGE_PATH)+"?t="+Date.now();}
    function apiUrl(){return "https://api.github.com/repos/"+OWNER+"/"+REPO+"/contents/"+encodeRepoPath(PACKAGE_PATH)+"?ref="+encodeURIComponent(BRANCH);}
    function isTransient(code){return code===408||code===429||code===500||code===502||code===503||code===504;}
    function requestRetry(opt,maxTry){
        var last=null,err=null;maxTry=maxTry||2;
        for(var i=1;i<=maxTry;i++){
            try{last=zdjl.requestUrl(opt);if(last&&!isTransient(last.code))return last;err=new Error("HTTP "+(last?last.code:"?"));}catch(e){err=e;}
            if(i<maxTry)try{zdjl.sleep(700*i);}catch(se){}
        }
        if(last)return last;throw err||new Error("网络请求失败");
    }
    function fetchPackage(){
        var r=null;
        try{
            r=requestRetry({url:rawUrl(),method:"GET",headers:[{"Accept":"application/json"}],timeout:60000},2);
            if(r&&r.code===200)return {resp:r,via:"raw"};
            if(r&&r.code===404)throw new Error("云端还没有 latest-package.json，请先用 V4.5.7 发布器发布一次");
        }catch(rawErr){
            if(String(rawErr).indexOf("latest-package.json")>=0)throw rawErr;
        }

        var token=getToken(),hs=[{"Accept":"application/vnd.github.raw+json"},{"X-GitHub-Api-Version":"2022-11-28"}];
        if(token)hs.unshift({"Authorization":"Bearer "+token});
        var api=requestRetry({url:apiUrl(),method:"GET",headers:hs,timeout:60000},2);
        if(api&&api.code===200)return {resp:api,via:"api"};
        if(api&&api.code===403&&!token)throw new Error("GitHub匿名API额度已用完；raw通道也不可用。可以稍后再试，或在版本更新器里设置只读Token。");
        throw new Error("下载最新版单包失败 HTTP "+(api?api.code:"?")+"\n"+(api&&api.body?api.body:""));
    }
    function safeName(name){return typeof name==="string"&&/^[^\\\/\x00-\x1f]+\.zjs$/i.test(name)&&name.indexOf("..")<0;}
    function validateScript(text,name){
        var lines=String(text||"").split(/\r?\n/),count=0;
        for(var i=0;i<lines.length;i++){
            if(!trimText(lines[i]))continue;
            var row=JSON.parse(lines[i]);
            if(!row||typeof row!=="object"||Array.isArray(row))throw new Error(name+"格式错误");
            if(count===0){if(row.type!==undefined||row.count===undefined||row.repeatCount===undefined)throw new Error(name+"文件头异常");}
            else if(!row.type)throw new Error(name+"动作类型缺失");
            count++;
        }
        if(count<2)throw new Error(name+"没有可执行动作");
    }
    function localText(path){try{return String(zdjl.readFile(path));}catch(e){return null;}}
    function backupName(name){return BASE_DIR+name+".bak";}
    function calledFromMain(){try{return String(zdjl.getVar("云工具由总控调用","global")||"")==="更新器";}catch(e){return false;}}
    function restoreJournal(){
        var path=BASE_DIR+".farm-update-transaction.json",raw=localText(path);if(!raw)return;
        var j;try{j=JSON.parse(raw);}catch(e){throw new Error("旧更新恢复日志损坏，请先备份脚本目录");}
        if(!j||j.status!=="writing"||!j.items)return;
        var bad=[];
        for(var i=0;i<j.items.length;i++){
            var it=j.items[i];if(!it||!safeName(it.name)||it.oldText===null)continue;
            try{zdjl.writeFile(BASE_DIR+it.name,it.oldText);if(localText(BASE_DIR+it.name)!==it.oldText)throw new Error("读回不一致");}catch(e2){bad.push(it.name);}
        }
        if(bad.length)throw new Error("上次更新恢复失败："+bad.join("、"));
        j.status="rolledBack";zdjl.writeFile(path,JSON.stringify(j));
    }

    try{
        restoreJournal();
        var got=fetchPackage();
        var pkg=JSON.parse(String(got.resp.body||""));
        if(!pkg||pkg.schema!==1||pkg.mode!=="single-package"||!Array.isArray(pkg.files))throw new Error("最新版单包格式不正确");
        if(Number(pkg.fileCount)!==pkg.files.length||pkg.files.length<1)throw new Error("最新版单包文件数不一致");

        var map={},order=[];
        for(var i=0;i<pkg.files.length;i++){
            var it=pkg.files[i],name=it&&String(it.name||""),content=it&&String(it.content==null?"":it.content);
            if(!safeName(name))throw new Error("单包存在非法文件名："+name);
            if(map[name]!==undefined)throw new Error("单包重复文件："+name);
            validateScript(content,name);map[name]=content;order.push(name);
        }

        // 依赖只在内存中解析，不执行任何下载到的代码。
        function visit(o,owner){
            if(!o||typeof o!=="object")return;
            if(o.type==="执行脚本"&&o.filePath){
                var dep=String(o.filePath);
                if(!safeName(dep))throw new Error(owner+" 依赖名称异常："+dep);
                if(map[dep]===undefined&&localText(BASE_DIR+dep)===null)throw new Error(owner+" 缺少依赖："+dep);
            }
            for(var k in o)if(Object.prototype.hasOwnProperty.call(o,k))visit(o[k],owner);
        }
        for(var oi=0;oi<order.length;oi++){
            var nm=order[oi],ls=map[nm].split(/\r?\n/);
            for(var li=0;li<ls.length;li++)if(trimText(ls[li]))visit(JSON.parse(ls[li]),nm);
        }

        var fromMain=calledFromMain(),staged=[],same=0,skippedMain=0;
        for(var si=0;si<order.length;si++){
            var n=order[si];
            if(fromMain&&n==="总控.zjs"){skippedMain=1;continue;}
            var old=localText(BASE_DIR+n),wanted=map[n];
            if(old===wanted)same++;else staged.push({name:n,oldText:old,text:wanted});
        }
        staged.sort(function(x,y){
            function rank(n){if(n==="农场脚本下载.zjs")return 3;if(n==="农场脚本版本更新器.zjs")return 2;if(n==="农场脚本版本发布器.zjs")return 1;return 0;}
            return rank(x.name)-rank(y.name);
        });

        if(!staged.length){
            zdjl.alert("已经是最新版｜"+(pkg.displayName||pkg.versionId||"")+"\n网络请求：1次（"+got.via+"）"+(skippedMain?"\n总控.zjs：运行中暂不覆盖":""));
            return;
        }

        var journalPath=BASE_DIR+".farm-update-transaction.json";
        var journal={status:"writing",version:pkg.versionId||"",items:staged};
        var jt=JSON.stringify(journal);zdjl.writeFile(journalPath,jt);if(localText(journalPath)!==jt)throw new Error("恢复日志写入失败，未覆盖脚本");

        try{
            for(var wi=0;wi<staged.length;wi++){
                var s=staged[wi];
                if(s.oldText!==null){zdjl.writeFile(backupName(s.name),s.oldText);if(localText(backupName(s.name))!==s.oldText)throw new Error(s.name+"备份失败");}
                zdjl.writeFile(BASE_DIR+s.name,s.text);if(localText(BASE_DIR+s.name)!==s.text)throw new Error(s.name+"写入校验失败");
            }
            journal.status="committed";zdjl.writeFile(journalPath,JSON.stringify(journal));
            zdjl.alert("单包更新完成｜"+(pkg.displayName||pkg.versionId||"")+"\n网络请求：1次（"+got.via+"）\n已更新/新建："+staged.length+"\n已经一致："+same+(skippedMain?"\n总控.zjs：运行中暂不覆盖；单独运行下载器即可更新":""));
        }catch(writeErr){
            var bad=[];
            for(var ri=0;ri<staged.length;ri++){
                var oldItem=staged[ri];if(oldItem.oldText===null)continue;
                try{zdjl.writeFile(BASE_DIR+oldItem.name,oldItem.oldText);if(localText(BASE_DIR+oldItem.name)!==oldItem.oldText)throw new Error("读回不一致");}catch(re){bad.push(oldItem.name);}
            }
            journal.status=bad.length?"writing":"rolledBack";try{zdjl.writeFile(journalPath,JSON.stringify(journal));}catch(ignore){}
            throw new Error("写入失败："+safeErrorText(writeErr)+(bad.length?"\n以下文件未恢复："+bad.join("、"):"\n原有文件已恢复"));
        }
    }catch(e){
        zdjl.alert("农场脚本单包下载失败\n\n"+safeErrorText(e));
    }
})();"}
